return {["scripts/actions/abilities/pets/venom.lua"]={["Path"]="scripts/actions/abilities/pets/venom.lua",["SHA256"]="7984b169ca37864539563251147877aa64c6a63766f23e7717ec82bbb07e3aeb",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'venom_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/venom_spray.lua"]={["Path"]="scripts/actions/abilities/pets/venom_spray.lua",["SHA256"]="d50cca1ede64d0f6b802db214cbe0dce03c8716f5d424711b0389f3c23285db9",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'venom_spray_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/water_ii.lua"]={["Path"]="scripts/actions/abilities/pets/water_ii.lua",["SHA256"]="560c2dccb742562bc0aac9894e19810df55eda66f073e73362ce355ae4165991",["Text"]="-----------------------------------\n-- Water II\n-- Family: Leviathan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WATER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WATER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/water_iv.lua"]={["Path"]="scripts/actions/abilities/pets/water_iv.lua",["SHA256"]="ee558f13bbb75e42f8d50e110da033ba3e3c744698c19fd40ecf9b8317ac59bb",["Text"]="-----------------------------------\n-- Water IV\n-- Family: Leviathan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WATER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WATER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/water_wall.lua"]={["Path"]="scripts/actions/abilities/pets/water_wall.lua",["SHA256"]="281f2f0e585f98c3d4f580daa80f1885d8da11429c30ac05e7491ad9824ddffe",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'water_wall_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/welt.lua"]={["Path"]="scripts/actions/abilities/pets/welt.lua",["SHA256"]="456925266e367a3c1f75fc14470720e43ae37199e0b952498bdf1994b0c5ec21",["Text"]="-----------------------------------\n-- Welt\n-- Family: Avatar (Siren)\n-- Description: Deals physical damage to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\n-- http://wiki.ffo.jp/html/37926.html\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 3.0, 3.0, 3.0 }\n    params.fTPSubsequentHits = { 3.0, 3.0, 3.0 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/whirl_claws.lua"]={["Path"]="scripts/actions/abilities/pets/whirl_claws.lua",["SHA256"]="0fa4c7c47fb91a5351fd9e007c835575358a82b257a10801d02153b79ff97f78",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'whirl_claws_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/whispering_wind.lua"]={["Path"]="scripts/actions/abilities/pets/whispering_wind.lua",["SHA256"]="524c1fb3f34f16466375eb4add47245f119033a163fc21ece4325c61a7c5838b",["Text"]="-----------------------------------\n-- Whispering Wind\n-- Family: Avatar (Garuda)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- TODO: AOE range scales with TP\n\n    local params = {}\n\n    params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n    params.baseHeal       = pet:getMainLvl() * 10 - 190\n\n    return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/wild_carrot.lua"]={["Path"]="scripts/actions/abilities/pets/wild_carrot.lua",["SHA256"]="b8cb9399175510b195360b9b2bc6997050d50fa59872f4d5a7f62ab33b703f19",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'wild_carrot_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/wild_oats.lua"]={["Path"]="scripts/actions/abilities/pets/wild_oats.lua",["SHA256"]="e9f5cee5e677cf71c0c67cb114c491d025b29bdd1763039ea612801bbf00b2c2",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'wild_oats_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/wind_blade.lua"]={["Path"]="scripts/actions/abilities/pets/wind_blade.lua",["SHA256"]="8920e76321d1aec8e6be57186fe34084e1e5a7a9179f45f0ca6b03d50fe04e2b",["Text"]="-----------------------------------\n-- Wind Blade\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.WIND_BLADE) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/wing_slap.lua"]={["Path"]="scripts/actions/abilities/pets/wing_slap.lua",["SHA256"]="7f124fb38b3d12c61acf0a9c43cdb6db571a79198b990b48f58bcd7415c1815c",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'wing_slap_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pflug.lua"]={["Path"]="scripts/actions/abilities/pflug.lua",["SHA256"]="36e3c9fdd91fc618151522e0c008f0f54ccddf5bc8ca9706ba3dd3a5931ed8c6",["Text"]="-----------------------------------\n-- Ability: Pflug\n-- Enhances resistance. The types of resistance enhanced depend upon the runes you harbor.\n-- Obtained: Rune Fencer Level 40\n-- Recast Time: 3:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.usePflug(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pianissimo.lua"]={["Path"]="scripts/actions/abilities/pianissimo.lua",["SHA256"]="20bf260728be47694685b7544c057b0218b4e2662913d2fa13a6cd159c4fb9d5",["Text"]="-----------------------------------\n-- Ability: Pianissimo\n-- Limits area of effect of next song to a single target.\n-- Obtained: Bard Level 20\n-- Recast Time: 0:00:15\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.bard.usePianissimo(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/presto.lua"]={["Path"]="scripts/actions/abilities/presto.lua",["SHA256"]="787db1e174472294e4a7eb5098eea7103d2a451c0948e6bc2b78a9d495681467",["Text"]="-----------------------------------\n-- Ability: Presto\n-- Description Enhances the effect of your next step and grants you an additional finishing move.\n-- Obtained: DNC Level 77\n-- Recast Time: 00:00:15 (Step)\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.usePrestoAbility(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/provoke.lua"]={["Path"]="scripts/actions/abilities/provoke.lua",["SHA256"]="7dbb260cb56df1f861dee4c2055ed38eeea356baf5168f401fb55834bbd87bec",["Text"]="-----------------------------------\n-- Ability: Provoke\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(user, target, ability)\n    --Leave blank.\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/puppet_roll.lua"]={["Path"]="scripts/actions/abilities/puppet_roll.lua",["SHA256"]="435133fb9721b69a12a4267f74d9dba98cbceac994d6543b1d581afd1956f2ea",["Text"]="-----------------------------------\n-- Ability: Puppet Roll\n-- Enhances pet magic attack and magic accuracy for party members within area of effect\n-- Optimal Job: Puppetmaster\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 52\n-- Phantom Roll +1 Value: 3\n--\n-- Die Roll    |No PUP  |With PUP\n-- --------    -------  ----------\n-- 1           |+4      |+12\n-- 2           |+5      |+13\n-- 3           |+18     |+26\n-- 4           |+7      |+15\n-- 5           |+9      |+17\n-- 6           |+10     |+18\n-- 7           |+2      |+10\n-- 8           |+11     |+19\n-- 9           |+13     |+21\n-- 10          |+15     |+23\n-- 11          |+22     |+30\n-- Bust        |-8      |-8\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/quickstep.lua"]={["Path"]="scripts/actions/abilities/quickstep.lua",["SHA256"]="b3426d740fcb8a0dcab9cd77de0e3dac6ea8d2801e9746628c8a40fc9cc43630",["Text"]="-----------------------------------\n-- Ability: Quickstep\n-- Lowers target's evasion. If successful, you will earn two Finishing Moves.\n-- Obtained: Dancer Level 20\n-- TP Required: 10%\n-- Recast Time: 00:05\n-- Duration: First Step lasts 1 minute, each following Step extends its current duration by 30 seconds.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkStepAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useStepAbility(player, target, ability, action, xi.effect.LETHARGIC_DAZE_1)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/rampart.lua"]={["Path"]="scripts/actions/abilities/rampart.lua",["SHA256"]="8a29dff231657229ff2468d2dadb6e7a1613dbfd42301125cf752925f3ec615b",["Text"]="-----------------------------------\n-- Ability: Rampart\n-- Grants all party members within the area of effect -25% SDT.\n-- SDT is multiplicative with regular Damage Taken; many forms of SDT are for a single type or element of damage\n-- However, Rampart's SDT is for all damage types.\n-- Obtained: Paladin Level 62\n-- Recast Time: 5:00\n-- Duration: 0:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.useRampart(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/random_deal.lua"]={["Path"]="scripts/actions/abilities/random_deal.lua",["SHA256"]="be3a03329e1f9356d939f3f1d1b017b66dea63dd9852a8226e1f572c044126cf",["Text"]="-----------------------------------\n-- Ability: Random Deal\n-- Has the possibility of resetting the reuse time of a job ability for each party member within area of effect.\n-- Obtained: Corsair Level 50\n-- Recast Time: 0:20:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    ability:setMsg(xi.msg.basic.JA_RECEIVES_EFFECT_3)\n    if not caster:doRandomDeal(target) then\n        ability:setMsg(xi.msg.basic.JA_MISS_2)\n    end\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/rapture.lua"]={["Path"]="scripts/actions/abilities/rapture.lua",["SHA256"]="2f314e2c2084f797243a61208bf2f0c321eedcba90748220ad03a7d9af1a43dd",["Text"]="-----------------------------------\n-- Ability: Rapture\n-- Enhances the potency of your next white magic spell.\n-- Obtained: Scholar Level 55\n-- Recast Time: Stratagem Charge\n-- Duration: 1 white magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.RAPTURE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.RAPTURE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.RAPTURE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/rayke.lua"]={["Path"]="scripts/actions/abilities/rayke.lua",["SHA256"]="55cf9cea7f42d1a58e779547638b91771e9966fdc40c6e31e1692b2940142e6f",["Text"]="-----------------------------------\n-- Ability: Rayke\n-- Expends runes to reduce elemental resistance of the target.\n-- Obtained: Rune Fencer level 75 (merit ability)\n-- Recast Time: 5:00\n-- Duration: 0:30 + an additional 3 for every merit after the first\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRayke(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/release.lua"]={["Path"]="scripts/actions/abilities/release.lua",["SHA256"]="16ba1ae222db6b31522833012c4f5b86fbd8424d3074579d014751a973800fc7",["Text"]="-----------------------------------\n-- Ability: Release\n-- Sends the avatar away.\n-- Obtained: Summoner Level 1\n-- Recast Time: 10 seconds (shared by all avatars)\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    target:despawnPet()\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/relinquish.lua"]={["Path"]="scripts/actions/abilities/relinquish.lua",["SHA256"]="c0fc19524a613a0493e63878b6bc535ef83a1bef93025f070ca9fabf93161497",["Text"]="-----------------------------------\n-- Ability: Relinquish\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.monstrosity.relinquishOnAbility(player)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/repair.lua"]={["Path"]="scripts/actions/abilities/repair.lua",["SHA256"]="f73a9ec81ad49ce03e6e4dcbdc2ed78a7d058d52f0ebab09977ce80a2291617a",["Text"]="-----------------------------------\n-- Ability: Repair\n-- Uses oil to restore pet's HP.\n-- Obtained: Puppetmaster Level 15\n-- Recast Time: 3:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckRepair(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.puppetmaster.onAbilityUseRepair(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/restoring_breath.lua"]={["Path"]="scripts/actions/abilities/restoring_breath.lua",["SHA256"]="e438369e7b1dc6adb1b86d1288c9c18466b37a3f466655170a80d8d0dc6effeb",["Text"]="-----------------------------------\n-- Ability: Restoring Breath\n-- Orders the wyvern to heal with its breath.\n-- Obtained: Dragoon Level 90\n-- Recast Time: 01:00\n-- Duration: instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\n-- TODO: find out what checks can result in being unable to use ability on the pet --\n-- such as if the wyvern has amnesia, stun, etc\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- You can't actually use Restoring Breath on retail unless your wyvern is up\n    -- This is on the pet menu, but just in case...\n    return xi.job_utils.dragoon.abilityCheckRequiresPet(player, target, ability, true)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    xi.job_utils.dragoon.useRestoringBreath(player, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/restraint.lua"]={["Path"]="scripts/actions/abilities/restraint.lua",["SHA256"]="f18d5abcbc23ba63c1b4542a1b365ccabf0416555b0dd5d5b5f30f83b97a5e6b",["Text"]="-----------------------------------\n-- Ability: Restraint\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useRestraint(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/retaliation.lua"]={["Path"]="scripts/actions/abilities/retaliation.lua",["SHA256"]="cba9876439845e7cb2d29b9c3ac69b4558a2bcdbe57441a5ab39a958ad7b161e",["Text"]="-----------------------------------\n-- Ability: Retaliation\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useRetaliation(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/retreat.lua"]={["Path"]="scripts/actions/abilities/retreat.lua",["SHA256"]="9279e2b06b107125efabc9f8923dee5a74c0aa9b0d46454bf1fd8ab498d6d76b",["Text"]="-----------------------------------\n-- Ability: Retreat\n-- Orders the avatar to hold back.\n-- Obtained: Summoner Level 1\n-- Recast Time: 10 sec\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:petRetreat()\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/retrieve.lua"]={["Path"]="scripts/actions/abilities/retrieve.lua",["SHA256"]="88a790edb54d1a779c36604c19423e08bf70786b2a28e942be18bbee7e0cf633",["Text"]="-----------------------------------\n-- Ability: Retrieve\n-- Orders your automaton to return to your side.\n-- Obtained: Puppetmaster Level 10\n-- Recast Time: 10 seconds\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckRetrieve(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseRetrieve(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/reverse_flourish.lua"]={["Path"]="scripts/actions/abilities/reverse_flourish.lua",["SHA256"]="896cebbcf41ed037034634f52bf52c65cb002cac207d261727f65da1734784db",["Text"]="-----------------------------------\n-- Ability: Reverse Flourish\n-- Converts remaining finishing moves into TP. Requires at least one Finishing Move.\n-- Obtained: Dancer Level 40\n-- Finishing Moves Used: 1-5\n-- Recast Time: 00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkFlourishAbility(player, target, ability, false, 1)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.useReverseFlourishAbility(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/reward.lua"]={["Path"]="scripts/actions/abilities/reward.lua",["SHA256"]="8ba1f0652a84aa3aa1fd8a9a3c03a16efe4bc273f9dc3c08c2c31d1c0bd85ea4",["Text"]="-----------------------------------\n-- Ability: Reward\n-- Feeds pet to restore its HP.\n-- Obtained: Beastmaster Level 12\n-- Recast Time: 1:30\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkReward(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useReward(player, target, ability)\nend\n\nreturn abilityObject\n"}};
